cat >> app.js <<'EOF'

document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return}
 const go=e.target.closest('[data-go]');if(go){setView(go.dataset.go);window.scrollTo({top:0,behavior:'smooth'});return}
 const p=e.target.closest('[data-project]');if(p){setView('missions');projectFilter=p.dataset.project;$('#breadcrumb').textContent=project(projectFilter).name;$('#pageTitle').innerHTML=esc(project(projectFilter).name)+'<span>.</span>';$('#pageSubtitle').textContent='Misiones de este proyecto, en un solo lugar.';render();return}
 const check=e.target.closest('[data-check]');if(check){if(repoMode){toast('La proyección del repositorio es de solo lectura.');return}let m=missions.find(x=>x.id===check.dataset.check);if(m){m.status=m.status==='done'?'planned':'done';m.horizon=m.status==='done'?'Completada':'Esta semana';save();render();toast(m.status==='done'?'Misión completada. ¡Buen trabajo!':'Misión reabierta.')}return}
});
$('#newMission').addEventListener('click',()=>{if(repoMode){toast('Edita orchestra/seed.json y ejecuta rebuild para actualizar el repo.');return}$('#missionForm').reset();$('#missionDialog').showModal();setTimeout(()=>$('#missionForm input').focus(),0)});
$('#closeDialog').addEventListener('click',()=>$('#missionDialog').close());$('#cancelDialog').addEventListener('click',()=>$('#missionDialog').close());
$('#missionDialog').addEventListener('click',e=>{if(e.target===$('#missionDialog'))$('#missionDialog').close()});
$('#missionForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);missions.unshift({id:'m-'+Date.now(),title:String(data.get('title')).trim(),project:data.get('project'),status:data.get('status'),horizon:data.get('horizon'),agent:'LU',start:1,length:3});save();$('#missionDialog').close();render();toast('Misión creada en este navegador.')});
$('#filterButton').addEventListener('click',()=>{let filters=['all','progress','planned','done'];statusFilter=filters[(filters.indexOf(statusFilter)+1)%filters.length];render()});
$('#timelineToggle').addEventListener('click',()=>{weekOffset=weekOffset?0:1;renderGantt()});
$('#addProject').addEventListener('click',()=>{if(repoMode){toast('Edita orchestra/seed.json para agregar proyectos al repo.');return}let name=prompt('Nombre del nuevo proyecto:');if(!name||!name.trim())return;projects.push({id:'p-'+Date.now(),name:name.trim().slice(0,40),color:colors[projects.length%colors.length]});save();render();toast('Proyecto creado en este navegador.')});
$('#dismissDemo').addEventListener('click',()=>$('.demo-notice').style.display='none');
$('#menuButton').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#helpButton').addEventListener('click',()=>window.open('ORCHESTRATION.md','_blank'));
$('#agentInfo').addEventListener('click',()=>toast(repoMode?'Heartbeat muestra la última señal registrada, no disponibilidad real.':'Estos agentes son datos de ejemplo.'));
$('#activityButton').addEventListener('click',()=>toast(repoMode?'Consulta orchestra/events/ para ver el historial del repositorio.':'Esta actividad es parte del workspace de ejemplo.'));
$('#sourceToggle').addEventListener('click',async()=>{
 if(repoMode){repoMode=false;projects=Array.isArray(saved.projects)?saved.projects:defaultProjects.map(x=>({...x}));missions=Array.isArray(saved.missions)?saved.missions:seedMissions.map(x=>({...x}));try{let local=JSON.parse(localStorage.getItem(storageKey)||'{}');if(Array.isArray(local.projects))projects=local.projects;if(Array.isArray(local.missions))missions=local.missions}catch(e){}agents=demoAgents.map(x=>({...x}));$('#sourceLabel').textContent='Datos de ejemplo';$('#noticeTitle').textContent='Estás viendo un workspace de ejemplo.';$('#noticeText').textContent='Explora libremente o crea tu primera misión.';$('#sourceToggle').textContent='Abrir datos del repo →';setView('overview');return}
 try{let response=await fetch('orchestra/state.json',{cache:'no-store'});if(!response.ok)throw Error('No disponible');let state=await response.json();if(!Array.isArray(state.projects)||!Array.isArray(state.missions)||!Array.isArray(state.agents))throw Error('Estado inválido');repoState=state;repoMode=true;projects=state.projects.map((p,i)=>({id:p.id,name:p.name,color:colors[i%colors.length]}));agents=state.agents.map((a,i)=>({id:a.id,name:a.name,role:a.role+' · '+(a.lastHeartbeat?'última señal '+new Date(a.lastHeartbeat).toLocaleString('es'):'sin heartbeat'),bg:['#e6efdf','#f3e8de','#e9edf4','#efebf3'][i%4],fg:['#6d8b67','#b28c72','#8293aa','#a090ae'][i%4],state:a.lastHeartbeat?'Señal registrada':'Sin señal',initials:a.name.slice(0,2).toUpperCase()}));missions=state.missions.map((m,i)=>({id:m.id,title:m.title,project:m.projectId,status:(state.protocol?.warnings?.length||m.claimStatus==='unknown')?'unknown':m.claimStatus==='conflict'?'conflict':m.status==='done'?'done':m.claimStatus==='claimed'?'progress':'planned',horizon:m.claimStatus==='claimed'?'Reclamada':m.claimStatus==='conflict'?'Revisar':'Sin fecha',agent:m.claims?.[0]?.agentId||'',start:0,length:0}));$('#sourceLabel').textContent='Proyección del repo';$('#noticeTitle').textContent=state.protocol?.warnings?.length?'Atención: el protocolo tiene advertencias.':'Datos del repositorio · solo lectura.';$('#noticeText').textContent=state.protocol?.warnings?.length?'No asumas disponibilidad; revisa orchestra/state.json.':'Instantánea local; sincroniza y reconstruye para actualizar.';$('#sourceToggle').textContent='Volver al ejemplo →';setView('overview');toast('Proyección del repositorio cargada.')}catch(err){toast('No se pudo leer el repo. Abre la app desde un servidor local.')}
});
hydrateIcons();render();
EOF

