function pulseGraphSVG() {
  const bins = Array(15).fill(0);
  state.activity.forEach(e => {
    const idx = clamp(Math.floor((REPLAY_DURATION - e.agoSeconds) / 60), 0, 14);
    bins[idx] += 1;
  });
  const max = Math.max(2, ...bins);
  const width = 300, height = 78, base = 66, step = 20;
  const points = bins.map((count, i) => {
    const x = 6 + i * step;
    const y = base - (count / max) * 44;
    return [x, y, count];
  });
  const line = points.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x},${y}`).join(' ');
  const area = `${line} L${points[points.length - 1][0]},${height} L${points[0][0]},${height} Z`;
  const bars = points.map(([x, y, count], i) => {
    if (!count) return '';
    return `<rect x="${x - 2.5}" y="${y}" width="5" height="${base - y}" rx="2.5" fill="rgba(196,229,171,${0.08 + Math.min(0.16, count / 30)})"/>`;
  }).join('');
  const dots = points.filter(p => p[2] > 0).map(([x, y, count]) => `<circle cx="${x}" cy="${y}" r="${count > 1 ? 2.2 : 1.5}" fill="#d4e9bf" opacity=".75"/>`).join('');
  return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Densidad de actividad en los últimos 15 minutos">
    <defs>
      <linearGradient id="pulseArea" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#b9dba0" stop-opacity=".28"/>
        <stop offset="1" stop-color="#b9dba0" stop-opacity="0"/>
      </linearGradient>
    </defs>
    <line x1="4" y1="${base}" x2="${width - 4}" y2="${base}" stroke="rgba(214,235,201,.12)" stroke-width=".7"/>
    ${bars}
    <path d="${area}" fill="url(#pulseArea)"/>
    <path d="${line}" fill="none" stroke="#c2dfa9" stroke-width="1.2" stroke-linejoin="round" opacity=".88"/>
    ${dots}
    <line x1="${width - 8}" y1="19" x2="${width - 8}" y2="${base + 3}" stroke="rgba(218,238,204,.24)" stroke-width=".7" stroke-dasharray="2 3"/>
    <circle cx="${width - 8}" cy="${points[14][1]}" r="2.5" fill="#dff0d1"/>
  </svg>`;
}

