303:     return false;
304:   }
305:   const base = `https://api.trello.com/1/boards/${encodeURIComponent(board)}`;
306:   const auth = `key=${encodeURIComponent(key)}&token=${encodeURIComponent(token)}`;
307:   try {
308:     const [listsRes, actionsRes] = await Promise.all([
309:       fetch(`${base}/lists?cards=open&card_fields=name,desc,idList,dateLastActivity,labels,shortUrl&${auth}`),
310:       fetch(`${base}/actions?filter=commentCard,updateCard,createCard&limit=20&fields=type,date,data&memberCreator=true&memberCreator_fields=fullName,username,initials&${auth}`)
311:     ]);
312:     if (!listsRes.ok) throw new Error(listsRes.status === 401 ? 'credenciales inválidas' : `Trello respondió ${listsRes.status}`);
313:     const lists = await listsRes.json();
314:     if (!Array.isArray(lists)) throw new Error('Respuesta de tablero inválida');
315:     const actionsRaw = actionsRes.ok ? await actionsRes.json() : [];
316:     const cards = lists.flatMap(l => (l.cards || []).map(c => ({ ...c, idList: l.id })));
317:     const actions = (Array.isArray(actionsRaw) ? actionsRaw : []).map(action => {
318:       let text = '';
