85: function isoWeek(date) {
86:   const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
87:   const dayNum = (d.getUTCDay() + 6) % 7;
88:   d.setUTCDate(d.getUTCDate() - dayNum + 3);
89:   const firstThursday = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
90:   return 1 + Math.round(((d - firstThursday) / 86400000 - 3 + ((firstThursday.getUTCDay() + 6) % 7)) / 7);
91: }
