.mini-plan-row .plan-copy { flex: 1; min-width: 0; }
.mini-plan-row strong { display: block; font-size: 9.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-plan-row small { display: block; font-size: 8px; color: #a0aaa2; margin-top: 2px; }
.mini-plan-row .mini-avatar { width: 21px; height: 21px; border-radius: 7px; overflow: hidden; }

/* Issues */
.source-tag { display: flex; align-items: center; gap: 6px; font-size: 8.5px; color: #91a094; margin-top: 10px; }
.status-dot { width: 5px; height: 5px; background: #7ca575; border-radius: 50%; display: inline-block; }
.issue-list { margin-top: 7px; }
.issue-row {
  display: flex; gap: 9px; align-items: flex-start; padding: 10px 0;
  border-top: 1px solid #f0f2ed; cursor: pointer; text-decoration: none; color: inherit;
}
.issue-row:first-child { border-top: 0; }
.issue-row:hover .issue-title { color: var(--green); }
.issue-icon { width: 19px; height: 19px; border-radius: 6px; background: #f1f4ee; display: grid; place-items: center; color: #7d8f80; flex: 0 0 auto; margin-top: 1px; }
.issue-icon svg { width: 11px; height: 11px; }
.issue-copy { flex: 1; min-width: 0; }
.issue-title { font-size: 10px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .15s; }
.issue-meta { display: flex; gap: 6px; align-items: center; margin-top: 3px; font: 400 7.5px var(--mono); color: #a2aca4; }
.issue-meta .open { color: #6e966c; }
.issue-meta .closed { color: #ae8379; }
.issue-meta .dot { width: 2px; height: 2px; border-radius: 50%; background: #c2cac2; }
.block-link { display: flex; align-items: center; justify-content: space-between; width: 100%; margin-top: 8px; padding-top: 11px; border-top: 1px solid #f0f2ed; text-align: left; }

/* Machine preview */
.machine-preview { display: flex; gap: 5px; margin-top: 13px; overflow: hidden; }
.machine-col { flex: 1; min-width: 0; background: #f6f6f1; border-radius: 8px; padding: 7px 5px; }
.machine-col-title { display: flex; justify-content: space-between; align-items: center; font: 500 7px var(--mono); color: #8e9a90; text-transform: uppercase; letter-spacing: .3px; margin-bottom: 5px; }
.machine-col-title span { color: #b1bab2; }
.machine-card { background: #fff; border: 1px solid #e8ebe5; border-radius: 5px; padding: 5px; margin-top: 4px; }
.machine-card strong { display: block; font-size: 7px; line-height: 1.3; font-weight: 600; height: 17px; overflow: hidden; }
.machine-card .machine-card-foot { display: flex; align-items: center; justify-content: space-between; margin-top: 4px; }
.machine-card .mini-agent-face { width: 13px; height: 13px; border-radius: 4px; overflow: hidden; }
.machine-card .machine-label { width: 12px; height: 3px; border-radius: 2px; }

645:.github-issues-block { margin-top: 15px; }
646:.issue-list.large .issue-row { padding: 11px 0; }
647:.issue-list.large .issue-title { font-size: 10.5px; }
648:.issue-list.large .issue-icon { width: 22px; height: 22px; border-radius: 7px; }
